parameters.functionCode:
const crm = $node['Get CRM KPIs'].json;
const seo = $node['Get SEO KPIs'].json;
const ops = $node['Get Operations KPIs'].json;

const revenueGrowth = crm.revenue_last_month > 0 
  ? Math.round((crm.revenue_mtd - crm.revenue_last_month) / crm.revenue_last_month * 100) 
  : 0;

const errorRate = ops.executions_24h > 0 
  ? Math.round(ops.errors_24h / ops.executions_24h * 100 * 10) / 10 
  : 0;

let emailRates = {};
try { emailRates = JSON.parse(ops.latest_email_rates || '{}'); } catch(e) {}

return [{
  json: {
    generated_at: new Date().toISOString(),
    crm: {
      new_leads_7d: parseInt(crm.new_leads_7d) || 0,
      new_leads_30d: parseInt(crm.new_leads_30d) || 0,
      total_customers: parseInt(crm.total_customers) || 0,
      hot_leads: parseInt(crm.hot_leads) || 0,
      avg_lead_score: parseInt(crm.avg_lead_score) || 0
    },
    sales: {
      active_deals: parseInt(crm.active_deals) || 0,
      pipeline_value: parseFloat(crm.pipeline_value) || 0,
      revenue_mtd: parseFloat(crm.revenue_mtd) || 0,
      revenue_growth_percent: revenueGrowth,
      deals_won_mtd: parseInt(crm.deals_won_mtd) || 0,
      deals_lost_mtd: parseInt(crm.deals_lost_mtd) || 0,
      win_rate: parseInt(crm.win_rate_30d) || 0
    },
    seo: {
      tracked_keywords: parseInt(seo.tracked_keywords) || 0,
      top10_keywords: parseInt(seo.top10_keywords) || 0,
      top3_keywords: parseInt(seo.top3_keywords) || 0,
      total_backlinks: parseInt(seo.total_backlinks) || 0,
      new_backlinks_7d: parseInt(seo.new_backlinks_7d) || 0,
      avg_backlink_dr: parseInt(seo.avg_backlink_dr) || 0
    },
    operations: {
      emails_sent_mtd: parseInt(ops.emails_sent_mtd) || 0,
      delivery_rate: emailRates.delivery_rate || 0,
      open_rate: emailRates.open_rate || 0,
      executions_24h: parseInt(ops.executions_24h) || 0,
      errors_24h: parseInt(ops.errors_24h) || 0,
      error_rate: errorRate
    }
  }
}];

